// IdentityServiceHandler is an implementation of the identity.IdentityService service.
type IdentityServiceHandler interface {
	// Authentication
	BeginOAuthLogin(context.Context, *connect.Request[identity.BeginOAuthLoginRequest]) (*connect.Response[identity.BeginOAuthLoginResponse], error)
	OAuthLogin(context.Context, *connect.Request[identity.OAuthLoginRequest]) (*connect.Response[identity.OAuthLoginResponse], error)
	RedeemOAuthCode(context.Context, *connect.Request[identity.RedeemOAuthCodeRequest]) (*connect.Response[identity.RedeemOAuthCodeResponse], error)
	PasswordSignup(context.Context, *connect.Request[identity.PasswordSignupRequest]) (*connect.Response[identity.PasswordSignupResponse], error)
	PasswordLogin(context.Context, *connect.Request[identity.PasswordLoginRequest]) (*connect.Response[identity.PasswordLoginResponse], error)
	// Passwordless email login (OTP code + magic link)
	RequestEmailLoginCode(context.Context, *connect.Request[identity.RequestEmailLoginCodeRequest]) (*connect.Response[identity.RequestEmailLoginCodeResponse], error)
	VerifyEmailLoginCode(context.Context, *connect.Request[identity.VerifyEmailLoginCodeRequest]) (*connect.Response[identity.VerifyEmailLoginCodeResponse], error)
	RequestMagicLink(context.Context, *connect.Request[identity.RequestMagicLinkRequest]) (*connect.Response[identity.RequestMagicLinkResponse], error)
	RedeemMagicLink(context.Context, *connect.Request[identity.RedeemMagicLinkRequest]) (*connect.Response[identity.RedeemMagicLinkResponse], error)
	// Phone verification (SMS OTP) — proves the authenticated caller owns a phone number
	RequestPhoneVerification(context.Context, *connect.Request[identity.RequestPhoneVerificationRequest]) (*connect.Response[identity.RequestPhoneVerificationResponse], error)
	VerifyPhoneCode(context.Context, *connect.Request[identity.VerifyPhoneCodeRequest]) (*connect.Response[identity.VerifyPhoneCodeResponse], error)
	// Session / Token Auth
	GetCurrentUser(context.Context, *connect.Request[identity.GetCurrentUserRequest]) (*connect.Response[identity.GetCurrentUserResponse], error)
	RefreshToken(context.Context, *connect.Request[identity.RefreshTokenRequest]) (*connect.Response[identity.RefreshTokenResponse], error)
	Logout(context.Context, *connect.Request[identity.LogoutRequest]) (*connect.Response[identity.LogoutResponse], error)
	// Self-service profile
	UpdateProfile(context.Context, *connect.Request[identity.UpdateProfileRequest]) (*connect.Response[identity.UpdateProfileResponse], error)
	// Password Management
	ChangePassword(context.Context, *connect.Request[identity.ChangePasswordRequest]) (*connect.Response[identity.ChangePasswordResponse], error)
	RequestPasswordReset(context.Context, *connect.Request[identity.RequestPasswordResetRequest]) (*connect.Response[identity.RequestPasswordResetResponse], error)
	ConfirmPasswordReset(context.Context, *connect.Request[identity.ConfirmPasswordResetRequest]) (*connect.Response[identity.ConfirmPasswordResetResponse], error)
	// Email Verification
	SendEmailVerification(context.Context, *connect.Request[identity.SendEmailVerificationRequest]) (*connect.Response[identity.SendEmailVerificationResponse], error)
	VerifyEmail(context.Context, *connect.Request[identity.VerifyEmailRequest]) (*connect.Response[identity.VerifyEmailResponse], error)
	// Email Change (primary-email rotation, double-opt-in)
	RequestEmailChange(context.Context, *connect.Request[identity.RequestEmailChangeRequest]) (*connect.Response[identity.RequestEmailChangeResponse], error)
	ConfirmEmailChange(context.Context, *connect.Request[identity.ConfirmEmailChangeRequest]) (*connect.Response[identity.ConfirmEmailChangeResponse], error)
	// Identity Verification (document + selfie via pluggable provider)
	BeginIdentityVerification(context.Context, *connect.Request[identity.BeginIdentityVerificationRequest]) (*connect.Response[identity.BeginIdentityVerificationResponse], error)
	GetIdentityVerificationStatus(context.Context, *connect.Request[identity.GetIdentityVerificationStatusRequest]) (*connect.Response[identity.GetIdentityVerificationStatusResponse], error)
	// Admin help (replaces self-serve ForgotPassword)
	RequestAdminHelp(context.Context, *connect.Request[identity.RequestAdminHelpRequest]) (*connect.Response[identity.RequestAdminHelpResponse], error)
	ListHelpRequests(context.Context, *connect.Request[identity.ListHelpRequestsRequest]) (*connect.Response[identity.ListHelpRequestsResponse], error)
	ResolveHelpRequest(context.Context, *connect.Request[identity.ResolveHelpRequestRequest]) (*connect.Response[identity.ResolveHelpRequestResponse], error)
	// Passkey / WebAuthn
	BeginPasskeyRegistration(context.Context, *connect.Request[identity.BeginPasskeyRegistrationRequest]) (*connect.Response[identity.BeginPasskeyRegistrationResponse], error)
	CompletePasskeyRegistration(context.Context, *connect.Request[identity.CompletePasskeyRegistrationRequest]) (*connect.Response[identity.CompletePasskeyRegistrationResponse], error)
	BeginPasskeyLogin(context.Context, *connect.Request[identity.BeginPasskeyLoginRequest]) (*connect.Response[identity.BeginPasskeyLoginResponse], error)
	CompletePasskeyLogin(context.Context, *connect.Request[identity.CompletePasskeyLoginRequest]) (*connect.Response[identity.CompletePasskeyLoginResponse], error)
	ListPasskeys(context.Context, *connect.Request[identity.ListPasskeysRequest]) (*connect.Response[identity.ListPasskeysResponse], error)
	DeletePasskey(context.Context, *connect.Request[identity.DeletePasskeyRequest]) (*connect.Response[identity.DeletePasskeyResponse], error)
	// QR Login (cross-device authorization)
	InitiateQrLogin(context.Context, *connect.Request[identity.InitiateQrLoginRequest]) (*connect.Response[identity.InitiateQrLoginResponse], error)
	GetQrLoginSession(context.Context, *connect.Request[identity.GetQrLoginSessionRequest]) (*connect.Response[identity.GetQrLoginSessionResponse], error)
	ApproveQrLogin(context.Context, *connect.Request[identity.ApproveQrLoginRequest]) (*connect.Response[identity.ApproveQrLoginResponse], error)
	PollQrLogin(context.Context, *connect.Request[identity.PollQrLoginRequest]) (*connect.Response[identity.PollQrLoginResponse], error)
	// 2FA TOTP
	BeginTotpSetup(context.Context, *connect.Request[identity.BeginTotpSetupRequest]) (*connect.Response[identity.BeginTotpSetupResponse], error)
	VerifyTotpSetup(context.Context, *connect.Request[identity.VerifyTotpSetupRequest]) (*connect.Response[identity.VerifyTotpSetupResponse], error)
	DisableTotp(context.Context, *connect.Request[identity.DisableTotpRequest]) (*connect.Response[identity.DisableTotpResponse], error)
	VerifyTotp(context.Context, *connect.Request[identity.VerifyTotpRequest]) (*connect.Response[identity.VerifyTotpResponse], error)
	RegenerateRecoveryCodes(context.Context, *connect.Request[identity.RegenerateRecoveryCodesRequest]) (*connect.Response[identity.RegenerateRecoveryCodesResponse], error)
	// Session management
	ListMySessions(context.Context, *connect.Request[identity.ListMySessionsRequest]) (*connect.Response[identity.ListMySessionsResponse], error)
	RevokeSession(context.Context, *connect.Request[identity.RevokeSessionRequest]) (*connect.Response[identity.RevokeSessionResponse], error)
	RevokeAllSessions(context.Context, *connect.Request[identity.RevokeAllSessionsRequest]) (*connect.Response[identity.RevokeAllSessionsResponse], error)
	SignOutEverywhere(context.Context, *connect.Request[identity.SignOutEverywhereRequest]) (*connect.Response[identity.SignOutEverywhereResponse], error)
	// Audit log
	ListAuditEvents(context.Context, *connect.Request[identity.ListAuditEventsRequest]) (*connect.Response[identity.ListAuditEventsResponse], error)
	// Users
	CreateUser(context.Context, *connect.Request[identity.CreateUserRequest]) (*connect.Response[identity.CreateUserResponse], error)
	GetUser(context.Context, *connect.Request[identity.GetUserRequest]) (*connect.Response[identity.GetUserResponse], error)
	UpdateUser(context.Context, *connect.Request[identity.UpdateUserRequest]) (*connect.Response[identity.UpdateUserResponse], error)
	DeleteUser(context.Context, *connect.Request[identity.DeleteUserRequest]) (*connect.Response[identity.DeleteUserResponse], error)
	// Admin-only paginated user listing — supports filters and search.
	ListUsers(context.Context, *connect.Request[identity.ListUsersRequest]) (*connect.Response[identity.ListUsersResponse], error)
	// Groups (formerly WorkingGroup — graph DB type still WorkingGroup)
	CreateGroup(context.Context, *connect.Request[identity.CreateGroupRequest]) (*connect.Response[identity.CreateGroupResponse], error)
	UpdateGroup(context.Context, *connect.Request[identity.UpdateGroupRequest]) (*connect.Response[identity.UpdateGroupResponse], error)
	DeleteGroup(context.Context, *connect.Request[identity.DeleteGroupRequest]) (*connect.Response[identity.DeleteGroupResponse], error)
	ListGroups(context.Context, *connect.Request[identity.ListGroupsRequest]) (*connect.Response[identity.ListGroupsResponse], error)
	// Membership (graph edges)
	AddGroupMember(context.Context, *connect.Request[identity.AddGroupMemberRequest]) (*connect.Response[identity.AddGroupMemberResponse], error)
	RemoveGroupMember(context.Context, *connect.Request[identity.RemoveGroupMemberRequest]) (*connect.Response[identity.RemoveGroupMemberResponse], error)
	ListGroupMembers(context.Context, *connect.Request[identity.ListGroupMembersRequest]) (*connect.Response[identity.ListGroupMembersResponse], error)
	// Organization signup (mode=multi only — returns Unimplemented in
	// mode=single). Creates a new tenant in tenant-shard-db, registers
	// the admin user globally, and creates the identity-layer
	// Organization + admin User rows scoped to the new tenant.
	OrganizationSignup(context.Context, *connect.Request[identity.OrganizationSignupRequest]) (*connect.Response[identity.OrganizationSignupResponse], error)
	// Tenant domains (redesign). Authenticated, project-scoped, and gated
	// on the caller being an owner/admin member of the target tenant — with
	// one exception: VerifyDomain on a still-latent tenant that has no
	// members yet is open, so the first verifier becomes its owner.
	// Available only on the postgres control-plane driver; entdb/memory
	// deployments return Unimplemented.
	CreateDomain(context.Context, *connect.Request[identity.CreateDomainRequest]) (*connect.Response[identity.CreateDomainResponse], error)
	VerifyDomain(context.Context, *connect.Request[identity.VerifyDomainRequest]) (*connect.Response[identity.VerifyDomainResponse], error)
	ListTenantDomains(context.Context, *connect.Request[identity.ListTenantDomainsRequest]) (*connect.Response[identity.ListTenantDomainsResponse], error)
	// Tenant membership (redesign). Authenticated, project-scoped, and —
	// except for AcceptTenantInvitation — gated on the caller being an
	// owner/admin member of the target tenant. AcceptTenantInvitation is the
	// redeemer's own action: any authenticated caller may redeem a token, but
	// only for an invitation addressed to their own account email. Available
	// only on the postgres control-plane driver; entdb/memory deployments
	// return Unimplemented.
	CreateTenantInvitation(context.Context, *connect.Request[identity.CreateTenantInvitationRequest]) (*connect.Response[identity.CreateTenantInvitationResponse], error)
	AcceptTenantInvitation(context.Context, *connect.Request[identity.AcceptTenantInvitationRequest]) (*connect.Response[identity.AcceptTenantInvitationResponse], error)
	ListTenantInvitations(context.Context, *connect.Request[identity.ListTenantInvitationsRequest]) (*connect.Response[identity.ListTenantInvitationsResponse], error)
	ListTenantMembers(context.Context, *connect.Request[identity.ListTenantMembersRequest]) (*connect.Response[identity.ListTenantMembersResponse], error)
	RemoveTenantMember(context.Context, *connect.Request[identity.RemoveTenantMemberRequest]) (*connect.Response[identity.RemoveTenantMemberResponse], error)
	// Admin user management (caller must have role=admin). Enforced in the
	// servicer via _require_admin(ctx); all admin RPCs audit-log their actions.
	InviteUser(context.Context, *connect.Request[identity.InviteUserRequest]) (*connect.Response[identity.InviteUserResponse], error)
	AcceptInvitation(context.Context, *connect.Request[identity.AcceptInvitationRequest]) (*connect.Response[identity.AcceptInvitationResponse], error)
	DeactivateUser(context.Context, *connect.Request[identity.DeactivateUserRequest]) (*connect.Response[identity.DeactivateUserResponse], error)
	ReactivateUser(context.Context, *connect.Request[identity.ReactivateUserRequest]) (*connect.Response[identity.ReactivateUserResponse], error)
	ResetUserPassword(context.Context, *connect.Request[identity.ResetUserPasswordRequest]) (*connect.Response[identity.ResetUserPasswordResponse], error)
	SetUserQuota(context.Context, *connect.Request[identity.SetUserQuotaRequest]) (*connect.Response[identity.SetUserQuotaResponse], error)
}

